import { Injectable, inject, DestroyRef } from '@angular/core';
import { BehaviorSubject, Observable, Subscription } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { map, shareReplay, tap } from 'rxjs/operators';
import { ValueDto } from '../models/value.model';
import { SpringApiResponse } from '../models/api/spring-api-response.model';
import { environment } from '../../environments/environment';
import { SyncUpdateService } from './sync/sync-update.service';

@Injectable({
  providedIn: 'root'
})
export class SharedDataService {
  private syncUpdateService = inject(SyncUpdateService);
  private destroyRef = inject(DestroyRef);

  private systemsSubject = new BehaviorSubject<ValueDto[]>([]);
  private equipmentTypesSubject = new BehaviorSubject<ValueDto[]>([]);
  private fileTypeSubject = new BehaviorSubject<ValueDto[]>([]);
  private vendorsSubject = new BehaviorSubject<ValueDto[]>([]);
  private isoPositionsSubject = new BehaviorSubject<ValueDto[]>([]);
  private normPositionsSubject = new BehaviorSubject<ValueDto[]>([]);
  private locationsSubject = new BehaviorSubject<ValueDto[]>([]);

  systems$: Observable<ValueDto[]> = this.systemsSubject.asObservable();
  equipmentTypes$: Observable<ValueDto[]> = this.equipmentTypesSubject.asObservable();
  fileTypes$: Observable<ValueDto[]> = this.fileTypeSubject.asObservable();
  vendors$: Observable<ValueDto[]> = this.vendorsSubject.asObservable();
  isoPositions$: Observable<ValueDto[]> = this.isoPositionsSubject.asObservable();
  normPositions$: Observable<ValueDto[]> = this.normPositionsSubject.asObservable();
  locations$: Observable<ValueDto[]> = this.locationsSubject.asObservable();

  private cachedSystems$: Observable<ValueDto[]> | null = null;
  private cachedEquipmentTypes$: Observable<ValueDto[]> | null = null;
  private cachedFileTypes$: Observable<ValueDto[]> | null = null;
  private cachedVendors$: Observable<ValueDto[]> | null = null;
  private cachedIsoPositions$: Observable<ValueDto[]> | null = null;
  private cachedNormPositions$: Observable<ValueDto[]> | null = null;
  private cachedLocations$: Observable<ValueDto[]> | null = null;

  private lotoAccessoryStatusesSubject = new BehaviorSubject<ValueDto[]>([]);
  lotoAccessoryStatuses$: Observable<ValueDto[]> = this.lotoAccessoryStatusesSubject.asObservable();
  private cachedLotoAccessoryStatuses$: Observable<ValueDto[]> | null = null;

  private lotoStatusesSubject = new BehaviorSubject<ValueDto[]>([]);
  lotoStatuses$: Observable<ValueDto[]> = this.lotoStatusesSubject.asObservable();
  private cachedLotoStatuses$: Observable<ValueDto[]> | null = null;

  private sseSubscription: Subscription | null = null;

  private url = environment.apiUrl + '/values';

  constructor(private http: HttpClient) {
    this.subscribeToValueUpdates();
    this.destroyRef.onDestroy(() => {
      this.sseSubscription?.unsubscribe();
    });
  }

  /**
   * Subscribe to SSE updates for Value entities.
   * When a Value is synced from another machine, refresh all category caches.
   */
  private subscribeToValueUpdates(): void {
    this.sseSubscription = this.syncUpdateService
      .getEntityTypeUpdates$('Value')
      .subscribe(event => {
        console.log('SharedDataService: Value entity updated via sync, refreshing caches', event);
        this.reloadAllData();
      });
  }

  private loadValuesOfCategory(category: string): Observable<ValueDto[]> {
    return this.http.get<SpringApiResponse<ValueDto[]>>(this.url + `/of-category/${category}`).pipe(
      map(response => response.responseData),
      shareReplay(1)
    );
  }

  loadSystems(): Observable<ValueDto[]> {
    if (!this.cachedSystems$) {
      this.cachedSystems$ = this.loadValuesOfCategory('system').pipe(
        tap(data => this.systemsSubject.next(data))
      );
    }
    return this.cachedSystems$;
  }

  loadFileTypes(): Observable<ValueDto[]> {
    if (!this.cachedFileTypes$) {
      this.cachedFileTypes$ = this.loadValuesOfCategory('fileType').pipe(
        tap(data => this.fileTypeSubject.next(data))
      );
    }
    return this.cachedFileTypes$;
  }

  loadVendors(): Observable<ValueDto[]> {
    if (!this.cachedVendors$) {
      this.cachedVendors$ = this.loadValuesOfCategory('vendor').pipe(
        tap(data => this.vendorsSubject.next(data))
      );
    }
    return this.cachedVendors$;
  }

  loadLocations(): Observable<ValueDto[]> {
    if (!this.cachedLocations$) {
      this.cachedLocations$ = this.loadValuesOfCategory('location').pipe(
        tap(data => this.locationsSubject.next(data))
      );
    }
    return this.cachedLocations$;
  }

  loadEqTypes(): Observable<ValueDto[]> {
    if (!this.cachedEquipmentTypes$) {
      this.cachedEquipmentTypes$ = this.loadValuesOfCategory('eqType').pipe(
        tap(data => this.equipmentTypesSubject.next(data))
      );
    }
    return this.cachedEquipmentTypes$;
  }
  
  loadIsoPositions(): Observable<ValueDto[]> {
    if (!this.cachedIsoPositions$) {
      this.cachedIsoPositions$ = this.loadValuesOfCategory('isoPos').pipe(
        tap(data => this.isoPositionsSubject.next(data))
      );
    }
    return this.cachedIsoPositions$;
  }

  loadNormPositions(): Observable<ValueDto[]> {
    if (!this.cachedNormPositions$) {
      this.cachedNormPositions$ = this.loadValuesOfCategory('normPos').pipe(
        tap(data => this.normPositionsSubject.next(data))
      );
    }
    return this.cachedNormPositions$;
  }
  
  loadLotoAccessoryStatuses(): Observable<ValueDto[]> {
    if (!this.cachedLotoAccessoryStatuses$) {
      this.cachedLotoAccessoryStatuses$ = this.loadValuesOfCategory('lotoAccessoryStatus').pipe(
        tap(data => this.lotoAccessoryStatusesSubject.next(data))
      );
    }
    return this.cachedLotoAccessoryStatuses$;
  }

  updateLotoAccessoryStatuses(statuses: ValueDto[]) {
    this.lotoAccessoryStatusesSubject.next(statuses);
  }

  updateSystems(systems: ValueDto[]) {
    this.systemsSubject.next(systems);
  }

  updateEquipmentTypes(types: ValueDto[]) {
    this.equipmentTypesSubject.next(types);
  }

  updateFileTypes(fileTypes: ValueDto[]) {
    this.fileTypeSubject.next(fileTypes);
  }

  updateVendors(vendors: ValueDto[]) {
    this.fileTypeSubject.next(vendors);
  }

  updateIsoPositions(isoPositions: ValueDto[]) {
    this.isoPositionsSubject.next(isoPositions);
  }
  
  updateNormPositions(normPositions: ValueDto[]) {
    this.normPositionsSubject.next(normPositions);
  }

  loadPermitStatuses(): Observable<ValueDto[]> {
    if (!this.cachedLotoStatuses$) {
      this.cachedLotoStatuses$ = this.loadValuesOfCategory('permitStatus').pipe(
        tap(data => this.lotoStatusesSubject.next(data))
      );
    }
    return this.cachedLotoStatuses$;
  }

  updateLotoStatuses(statuses: ValueDto[]) {
    this.lotoStatusesSubject.next(statuses);
  }



  clearCache() {
    this.cachedSystems$ = null;
    this.cachedEquipmentTypes$ = null;
    this.cachedFileTypes$ = null;
    this.cachedIsoPositions$ = null;
    this.cachedNormPositions$ = null;
    this.cachedLotoAccessoryStatuses$ = null;
    this.cachedLotoStatuses$ = null;
    this.cachedVendors$ = null;
    this.cachedLocations$ = null;
  
    // Reset BehaviorSubjects
    this.systemsSubject.next([]);
    this.equipmentTypesSubject.next([]);
    this.fileTypeSubject.next([]);
    this.vendorsSubject.next([]);
    this.isoPositionsSubject.next([]);
    this.normPositionsSubject.next([]);
    this.lotoAccessoryStatusesSubject.next([]);
    this.lotoStatusesSubject.next([]);
    this.locationsSubject.next([]);
  }

  reloadAllData() {
    
    // Clear the cache first
    this.clearCache();
  
    // Load all data and update BehaviorSubjects
    this.loadSystems().subscribe();
    this.loadEqTypes().subscribe();
    this.loadFileTypes().subscribe();
    this.loadIsoPositions().subscribe();
    this.loadNormPositions().subscribe();
    this.loadLotoAccessoryStatuses().subscribe();
    this.loadPermitStatuses().subscribe();
    this.loadVendors().subscribe();
    this.loadLocations().subscribe();
  }
}